                <div class="flex gap-2">
                  <select id="rnp-month-from" class="rounded-xl px-2 py-2 text-sm flex-1" style="background:var(--surface);border:1px solid var(--border);color:var(--text-primary)">${s(6,x.monthFrom)}</select>
                  <select id="rnp-month-to" class="rounded-xl px-2 py-2 text-sm flex-1" style="background:var(--surface);border:1px solid var(--border);color:var(--text-primary)">${s(12,x.monthTo)}</select>
                </div>
